challenges.solution:
values = [5, 2.5, "hello", True, None, 2+3j]
for value in values:
    print(type(value).__name__)

number = int(input())
if number > 0:
    print("positive")
elif number < 0:
    print("negative")
else:
    print("zero")

raw = input()
try:
    number = int(raw)
except ValueError:
    print("Invalid integer")
else:
    print(number * 2)

numerator = float(input())
denominator = float(input())
if denominator == 0:
    print("Undefined")
else:
    print(f"{numerator / denominator * 100:.2f}%")

raw = input()
try:
    value = int(raw, 2)
except ValueError:
    print("Invalid binary")
else:
    print(value)
    print(hex(value))
    print(oct(value))
